3042	// ===========================================================================
3043	// MIGRATED SYSTEMD UNITS — EXEC PRE-FLIGHT + HEALTH GATE
3044	// ===========================================================================
3045	/**
3046	 * A unit file is the one thing in a migration that is copied VERBATIM and then
3047	 * executed. Everything inside it — interpreter path, working directory, build
3048	 * artefacts — is a statement about the OLD machine, and none of it is checked
3049	 * before `systemctl enable --now` runs.
3050	 *
3051	 * Real incident, 2026-07-25 (and this had happened BEFORE — it is field note #13,
3052	 * documented after a previous migration and it recurred anyway, which is exactly
3053	 * why it is now an executable pre-flight instead of a paragraph in a document):
3054	 *
3055	 *     nexis-next.service
3056	 *       ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
3057	 *
3058	 * The source had a hand-installed Node at /usr/local/bin/node. The target has
3059	 * apt's Node 20 at /usr/bin/node and NOTHING at /usr/local/bin/node, so systemd
3060	 * failed the exec with status 203/EXEC. The unit crash-looped 78 times and the
3061	 * migration reported SUCCESS.
3062	 *
3063	 * So: before enabling anything, resolve the absolute executable of every
3064	 * ExecStart / ExecStartPre / ExecStartPost. Missing ⇒ symlink to the same binary
3065	 * found elsewhere on the target, else copy it from the source, else BLOCK and say
3066	 * exactly which unit wants exactly which path.
3067	 */
3068	export type UnitExecRef = { directive: string; path: string };
3069	
3070	/**
3071	 * Fold systemd's line continuations. A unit may legally spread one ExecStart over
3072	 * several lines with a trailing backslash, and reading it line-at-a-time would
3073	 * see a directive whose command is empty and skip the check entirely.
3074	 */
3075	export function unfoldUnitLines(text: string): string[] {
3076	  const out: string[] = [];
3077	  let acc = "";
3078	  for (const raw of String(text ?? "").split("\n")) {
3079	    const line = raw.replace(/\r$/, "");
3080	    if (/\\\s*$/.test(line)) {
3081	      acc += line.replace(/\\\s*$/, " ");
3082	      continue;
3083	    }
3084	    out.push((acc + line).trim());
3085	    acc = "";
3086	  }
3087	  if (acc.trim()) out.push(acc.trim());
3088	  return out;
3089	}
3090	
3091	/**
3092	 * Every ABSOLUTE executable path a unit's Exec* directives will try to run.
3093	 *
3094	 * Defensive by design, because a unit file is untrusted input from another
3095	 * machine:
3096	 *   - `ExecStart=-/path`  the `-` (ignore failure), `@` (argv[0] override),
3097	 *     `+` (full privileges), `!` / `!!` (no-setuid variants) prefixes may appear
3098	 *     in any order and combination and are stripped before the path is read;
3099	 *   - quoted paths (`ExecStart="/opt/my app/bin/run" --flag`) are unquoted;
3100	 *   - an EMPTY assignment (`ExecStart=`) is systemd's list-reset and is skipped;
3101	 *   - a bare command (`ExecStart=node server.js`) is resolved from PATH by
3102	 *     systemd itself, so it is deliberately IGNORED — we cannot check it and
3103	 *     guessing would be worse than silence;
3104	 *   - a path carrying a `%` specifier (`/usr/bin/%i`) can only be resolved by
3105	 *     systemd, so it is skipped rather than mis-reported. It also would not pass
3106	 *     PATH_RE, which is what keeps every value here shell-inert.
3107	 */
3108	export function parseUnitExecPaths(text: string): UnitExecRef[] {
3109	  const out: UnitExecRef[] = [];
3110	  const seen = new Set<string>();
3111	  for (const line of unfoldUnitLines(text)) {
3112	    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
3113	    if (!m) continue;
3114	    let rhs = m[2].trim();
3115	    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
3116	    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
3117	    if (!rhs) continue;
3118	    let exe: string;
3119	    const q = rhs[0];
3120	    if (q === '"' || q === "'") {
3121	      const end = rhs.indexOf(q, 1);
3122	      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
3123	    } else {
3124	      exe = rhs.split(/\s+/)[0] ?? "";
3125	    }
3126	    exe = exe.trim();
3127	    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
3128	    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
3129	    const key = `${m[1]}|${exe}`;
3130	    if (seen.has(key) || out.length >= 12) continue;
3131	    seen.add(key);
3132	    out.push({ directive: m[1], path: exe });
3133	  }
3134	  return out;
3135	}
