3137	/**
3138	 * Everything `preflightUnitExecs` needs from the target machine, as an
3139	 * interface rather than a `Client`.
3140	 *
3141	 * WHY: field note #13 ("resolve ExecStart binaries") was written after a unit
3142	 * crash-looped 880 times, was never implemented, and the SAME failure came back
3143	 * four months later as #25 (`/usr/local/bin/node`, 78 restarts, migration
3144	 * reported success). The fix is only a fix if it stays correct, and it can only
3145	 * be kept correct by a test — so the one decision ladder that stands between a
3146	 * copied unit and a permanent crash-loop is driven through this seam and
3147	 * exercised by `test/migration-gate.test.ts` with a fake host. Nothing here is
3148	 * mocked in production: `sshUnitExecHost` is the only implementation the engine
3149	 * uses.
3150	 */
3151	export type UnitExecHost = {
3152	  /** The unit file's text; "" when it cannot be read. */
3153	  readUnitFile: (unitFile: string) => Promise<string>;
3154	  /** `test -x` — present AND executable. */
3155	  isExecutable: (path: string) => Promise<boolean>;
3156	  /** `test -e` — present at all (a non-executable file is still a 203/EXEC cause). */
3157	  exists: (path: string) => Promise<boolean>;
3158	  /** `command -v <basename>` — the same program installed under a different prefix. */
3159	  whichSameName: (basename: string) => Promise<string>;
3160	  /**
3161	   * `<path> --version` on the TARGET, and the same path's version on the SOURCE.
3162	   * Returns "" when the version cannot be read.
3163	   *
3164	   * WHY: step 1 of the repair ladder links a missing `/usr/local/bin/node` to
3165	   * whatever `node` the target happens to have and told the customer it was "the
3166	   * same program, installed in a different place". A source running Node 20 and a
3167	   * target with Node 12 are NOT the same program — the unit stops failing 203/EXEC
3168	   * and starts failing at runtime instead, which is harder to diagnose and reads
3169	   * as a successful repair. A version we did not compare is a claim we cannot make.
3170	   */
3171	  versionOf: (path: string) => Promise<string>;
3172	  versionOnSource: (path: string) => Promise<string>;
3173	  /** `mkdir -p <dir> && ln -s <target> <linkPath>`; true only if the link now execs. */
3174	  symlink: (opts: { target: string; linkPath: string; dir: string }) => Promise<boolean>;
3175	  /**
3176	   * TARGET-ONLY. Install the given MAJOR of a language runtime so a migrated unit
3177	   * built against it can actually run, instead of being handed to the customer as
3178	   * a "install Node 22 yourself" blocker. Only `node`/`nodejs` is automated today
3179	   * (via NodeSource, apt only). Returns the resolved interpreter path once the
3180	   * target reports that major, or "" when it could not — unsupported runtime, no
3181	   * apt, offline, or a version that still doesn't match — in which case the caller
3182	   * falls back to the blocker. Only ever INSTALLS; never removes or downgrades
3183	   * anything the box already relied on, so it is the same class of create-only
3184	   * action as `symlink` above.
3185	   */
3186	  installRuntimeMajor: (runtime: string, major: string) => Promise<string>;
3187	};
3188	
3189	/** The real, SSH-backed UnitExecHost — the only one production ever uses. */
3190	function sshUnitExecHost(conn: Client, onSource: (cmd: string) => string): UnitExecHost {
3191	  return {
3192	    readUnitFile: async (unitFile) => (await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS)).stdout,
3193	    isExecutable: (path) => shOk(conn, `test -x ${path}`),
3194	    exists: (path) => shOk(conn, `test -e ${path}`),
3195	    whichSameName: async (base) => clean((await sh(conn, `command -v ${base} 2>/dev/null`)).stdout, 255),
3196	    versionOf: async (path) =>
3197	      validPath(path) ? clean((await sh(conn, `${path} --version 2>/dev/null | head -n 1`, SETUP_TIMEOUT_MS)).stdout, 120) : "",
3198	    versionOnSource: async (path) =>
3199	      validPath(path)
3200	        ? clean((await sh(conn, `${onSource(`${path} --version 2>/dev/null | head -n 1`)}`, SETUP_TIMEOUT_MS)).stdout, 120)
3201	        : "",
3202	    symlink: async ({ target, linkPath, dir }) => {
3203	      // `ln -s` (not -sfn): we already proved the path is absent, so a plain
3204	      // symlink can never clobber anything. If a race created it meanwhile we
3205	      // want the loud failure, not a silent replacement.
3206	      const ok = await shOk(conn, `mkdir -p ${dir} && ln -s ${target} ${linkPath}`);
3207	      return ok && (await shOk(conn, `test -x ${linkPath}`));
3208	    },
3209	    installRuntimeMajor: async (runtime, major) => {
3210	      const rt = String(runtime ?? "").toLowerCase();
3211	      const mj = String(major ?? "");
3212	      if (!/^\d{1,4}$/.test(mj)) return ""; // guards the interpolation below
3213	      if (rt !== "node" && rt !== "nodejs") return ""; // only Node is automated today
3214	      // NodeSource on a Debian/Ubuntu (apt) target. Other package managers fall
3215	      // back to the blocker rather than guessing at a repo. Bounded like any
3216	      // other package install. `setup_<major>.x` adds the repo AND runs an update;
3217	      // `apt-get install -y nodejs` then upgrades /usr/bin/node in place.
3218	      const fetch = `(command -v curl >/dev/null 2>&1 && curl -fsSL https://deb.nodesource.com/setup_${mj}.x || wget -qO- https://deb.nodesource.com/setup_${mj}.x)`;
3219	      const ok = await shOk(
3220	        conn,
3221	        `command -v apt-get >/dev/null 2>&1 && ${fetch} | bash - && DEBIAN_FRONTEND=noninteractive apt-get install -y nodejs`,
3222	        INSTALL_TIMEOUT_MS
3223	      );
3224	      if (!ok) return "";
3225	      const path = clean((await sh(conn, `command -v node 2>/dev/null`)).stdout, 255);
3226	      if (!path || !validPath(path)) return "";
3227	      const ver = clean((await sh(conn, `${path} --version 2>/dev/null | head -n 1`, SETUP_TIMEOUT_MS)).stdout, 120);
3228	      return majorVersion(ver) === mj ? path : "";
3229	    },
3230	  };
3231	}
3232	
3233	/**
3234	 * The major version out of a `--version` line, or "" when there isn't one.
3235	 *
3236	 * Handles the shapes real programs actually print: `v20.11.1` (node),
3237	 * `Python 3.11.2`, `ruby 3.1.4p223`, `PHP 8.2.7 (cli)`, `go version go1.21.5`.
3238	 * Deliberately returns "" rather than a guess — an unknown version must not be
3239	 * compared, because a false mismatch is as misleading as a missed one.

3240	 */
3241	export function majorVersion(s: string): string {
3242	  const m = /(?:^|[^\d.])v?(\d{1,4})\.\d/.exec(String(s ?? ""));
3243	  return m ? m[1] : "";
3244	}
3245	
3246	/**
3247	 * Programs whose `--version` this engine is willing to actually RUN.
3248	 *
3249	 * WHY AN ALLOWLIST AND NOT "anything with a validated path".
3250	 *
3251	 * The version comparison added for rehearsal defect 10 (a Node 20 app linked to
3252	 * a Node 12 interpreter and reported as "the same program") calls
3253	 * `host.versionOnSource(ref.path)` — which executes `<path> --version` ON THE
3254	 * SOURCE MACHINE, over SSH, in the middle of a cutover. `ref.path` is whatever
3255	 * the customer's copied unit file names in its `ExecStart`, and that is very
3256	 * often not an interpreter:
3257	 *
3258	 *     ExecStart=/opt/app/bin/deploy.sh
3259	 *     ExecStart=/usr/local/bin/reset-and-seed
3260	 *
3261	 * `deploy.sh --version` is a script that has never heard of `--version`. Most
3262	 * ignore unknown arguments and just run. The engine's entire safety promise is
3263	 * that the SOURCE is only ever READ FROM — that is what makes "point DNS back"
3264	 * a complete rollback — and running the customer's own scripts on their live
3265	 * old server silently voids it. PATH_RE validation makes the string safe to put
3266	 * in a command; it says nothing at all about what executing it does.
3267	 *
3268	 * So the version probe is restricted to language runtimes and interpreters,
3269	 * where `--version` is a documented flag that prints a banner and exits. That is
3270	 * exactly the population the check was written for (field notes 13/14/25 are all
3271	 * interpreter-path failures) and it costs the check nothing: for anything else
3272	 * we simply do not claim to have compared versions — see the repair wording in
3273	 * `preflightUnitExecs`.
3274	 *
3275	 * `python3.11`, `php8.2`, `php-fpm8.1` and friends are covered because a
3276	 * versioned basename is the normal shape on Debian/RHEL.
3277	 */
3278	const VERSION_PROBE_SAFE_RE =
3279	  /^(node|nodejs|deno|bun|python|python\d(\.\d{1,2})?|pypy\d?|php|php\d(\.\d)?|php-fpm|php-fpm\d(\.\d)?|ruby|perl|java|dotnet|go|erl|gunicorn|uvicorn|uwsgi|pnpm|npm|yarn)$/;
3280	
3281	/**
3282	 * True when running `<basename> --version` is a read-only act on someone else's
3283	 * live server. Deliberately conservative: an unknown program is not probed, and
3284	 * an unprobed program is never described as "the same program".
3285	 */
3286	export function versionProbeSafe(basename: string): boolean {
3287	  return VERSION_PROBE_SAFE_RE.test(String(basename ?? ""));
3288	}
3289	
3290	/**
3291	 * What to tell the customer about a service whose unit file we could NOT pull
3292	 * from the source's `/etc/systemd/system`.
3293	 *
3294	 * Incident (2026-07-26 rehearsal): the rsync fails for every DISTRO-packaged
3295	 * unit, because those live in `/lib/systemd/system`, not `/etc`. The code then
3296	 * pushed one identical action item per unit — "unit not a simple
3297	 * /etc/systemd/system file — re-enable manually" — for `containerd`, `docker`,
3298	 * `exim4`, `mariadb`, `nginx`, `qemu-guest-agent` and `serial-getty@ttyS0`.
3299	 * Seven of the run's twenty-two `needsAttention` entries were instructions to
3300	 * hand-re-enable software the target had already installed and already had
3301	 * RUNNING, in the same summary that said `nginx restarted`. It also contradicts
3302	 * field note 27's rule about not re-enabling a web server off the source's list.
3303	 *
3304	 * Noise is not harmless here: the two entries that were real were buried in it.
3305	 *
3306	 * The verdict is driven ONLY by what was actually observed on the target, never
3307	 * by a package-name allowlist — the point is to stop guessing, not to guess
3308	 * differently.
3309	 */
3310	export function distroUnitVerdict(input: {
3311	  svc: string;
3312	  /** `systemctl list-unit-files <svc>.service` found it on the TARGET. */
3313	  presentHere: boolean;
3314	  /** `systemctl is-active <svc>` said active on the TARGET. */
3315	  activeHere: boolean;
3316	}): { status: MigrationStepResult["status"]; detail: string } {
3317	  const { svc, presentHere, activeHere } = input;
3318	  if (activeHere) {
3319	    return {
3320	      status: "running",
3321	      detail: `this server provides ${svc} itself and it is already running — the old server's copy was a distribution package, not a custom unit, so there is nothing to move`,
3322	    };
3323	  }
3324	  if (presentHere) {
3325	    return {
3326	      status: "copied",
3327	      detail: `${svc} is installed on this server but is not running. It was a distribution package on the old server, so there is no custom unit to copy. If your setup needs it: systemctl enable --now ${svc}`,
3328	    };
3329	  }
3330	  return {
3331	    status: "copied",
3332	    detail:
3333	      `${svc} ran on the old server but its unit is not a plain /etc/systemd/system file, and this server does not have ${svc} at all — ` +
3334	      `so it was NOT migrated and nothing here provides it. Install it and enable it: apt-get install -y ${svc} && systemctl enable --now ${svc}`,
3335	  };
3336	}
3337	
3338	/**
3339	 * Resolve every missing Exec* binary for one unit BEFORE it is enabled.
3340	 * Returns the human-readable repairs made and a blocking entry for anything we
3341	 * refused to guess at. Never throws; never removes or overwrites anything —
3342	 * every action here only ever CREATES a path that did not exist.
3343	 */
3344	export async function preflightUnitExecs(opts: {
3345	  host: UnitExecHost;
3346	  unit: string;
3347	  unitFile: string;
3348	  existsOnSource: (path: string) => Promise<boolean>;
3349	  copyFromSource: (path: string) => Promise<boolean>;
3350	  say: (line: string) => Promise<void>;
3351	}): Promise<{ ok: boolean; repairs: string[]; blockers: PendingItem[] }> {
3352	  const { host, unit, unitFile, existsOnSource, copyFromSource, say } = opts;
3353	  const repairs: string[] = [];
3354	  const blockers: PendingItem[] = [];
3355	  if (!SVCNAME_RE.test(unit) || !validPath(unitFile)) return { ok: true, repairs, blockers };
3356	
3357	  const refs = parseUnitExecPaths(await host.readUnitFile(unitFile));
3358	  for (const ref of refs) {
3359	    if (await host.isExecutable(ref.path)) continue;
3360	
3361	    // It exists but is not executable — a real 203/EXEC cause too. Reported, not
3362	    // silently chmod-ed: changing the mode of the customer's own file is their
3363	    // call, and the command to do it is one line.
3364	    if (await host.exists(ref.path)) {
3365	      blockers.push({
3366	        domain: `${unit}.service`,
3367	        why: `its ${ref.directive} runs ${ref.path}, which exists on this server but is not executable — systemd will fail it with 203/EXEC`,
3368	        fix: `chmod +x ${ref.path} && systemctl restart ${unit}`,
3369	      });
3370	      continue;
3371	    }
3372	
3373	    // 1. The SAME program under a different prefix. This is the common case:
3374	    //    /usr/local/bin/node (hand-installed on the source) vs /usr/bin/node
3375	    //    (apt, on the target). A symlink makes the copied unit correct without
3376	    //    editing the customer's unit file.
3377	    const base = ref.path.slice(ref.path.lastIndexOf("/") + 1);
3378	    const dir = parentDir(ref.path);
3379	    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(base) && validPath(dir)) {
3380	      const found = await host.whichSameName(base);
3381	      if (found && found !== ref.path && validPath(found) && (await host.isExecutable(found))) {
3382	        if (await host.symlink({ target: found, linkPath: ref.path, dir })) {
3383	          // "The same program" is a claim, and until now it was made without ever
3384	          // checking. Compare the MAJOR versions across the two machines: linking
3385	          // a Node 20 app at a Node 12 interpreter stops the 203/EXEC and starts a
3386	          // runtime failure instead, which looks like a successful repair and is
3387	          // harder for the customer to diagnose. We still make the link (a wrong
3388	          // version at least produces a real error message rather than nothing),
3389	          // but a mismatch is reported as a blocker, not as a repair.
3390	          //
3391	          // The probe is gated on `versionProbeSafe` because `versionOnSource`
3392	          // EXECUTES this path on the customer's live old server. See its comment:
3393	          // running `deploy.sh --version` there would break the one promise that
3394	          // makes a migration reversible.
3395	          const probeSafe = versionProbeSafe(base);
3396	          const [srcVer, dstVer] = probeSafe
3397	            ? await Promise.all([host.versionOnSource(ref.path), host.versionOf(found)])
3398	            : ["", ""];
3399	          const srcMajor = majorVersion(srcVer);
3400	          const dstMajor = majorVersion(dstVer);
3401	          if (srcMajor && dstMajor && srcMajor !== dstMajor) {
3402	            // Try to make the TARGET match instead of handing the customer a
3403	            // to-do: install the source's major of this runtime and confirm the
3404	            // unit's interpreter now resolves to it. This is a target-only
3405	            // install (the same create-only class as the symlink just made), and
3406	            // it turns "your app is built for Node 22, this box has Node 20, here
3407	            // is how to fix it" into a service that simply starts — the exact
3408	            // 2026-07-27 case where nexis-staging and five sibling apps were dead
3409	            // purely on Node 22-vs-20. Only claimed when the post-install version
3410	            // actually matches; otherwise we fall through to the blocker.
3411	            const installedPath = versionProbeSafe(base) ? await host.installRuntimeMajor(base, srcMajor) : "";
3412	            if (installedPath && majorVersion(await host.versionOf(ref.path)) === srcMajor) {
3413	              repairs.push(
3414	                `${unit}: the old server built this against ${base} ${srcMajor} but this server had ${base} ${dstMajor} — installed ${base} ${srcMajor}, and ${ref.path} now runs it`
3415	              );
3416	              await say(
3417	                `  ${unit}: this box had ${base} ${dstMajor} but your app needs ${base} ${srcMajor}; installed ${base} ${srcMajor} so the service can start.`
3418	              );
3419	              continue;
3420	            }
3421	            blockers.push({
3422	              domain: `${unit}.service`,
3423	              why:
3424	                `its ${ref.directive} runs ${ref.path}. That program is not on this server, so it was linked to ${found} — but the old server had ` +
3425	                `${base} ${srcVer} and this one has ${base} ${dstVer}. That is a different major version, and an application built against ` +
3426	                `${base} ${srcMajor} will usually not run on ${base} ${dstMajor}`,
3427	              fix:
3428	                `install ${base} ${srcMajor} on this server (for Node: curl -fsSL https://deb.nodesource.com/setup_${srcMajor}.x | bash - && apt-get install -y nodejs), ` +
3429	                `then run: systemctl restart ${unit}`,
3430	            });
3431	            await say(
3432	              `  ${unit}: ${ref.path} was linked to ${found}, but the versions DIFFER — old server ${srcVer}, this server ${dstVer}. Check this service.`
3433	            );
3434	            continue;
3435	          }
3436	          // "The same program, installed in a different place" is a MEASUREMENT,
3437	          // not a courtesy. It is said only when both majors were read and matched.
3438	          // When they were not — an unreadable banner, or a program we refuse to
3439	          // execute on the source — the link is still made (it is the best
3440	          // available repair) but the claim is not, because a claim we did not
3441	          // verify is the defect this whole engine is built around. Rehearsal
3442	          // defect 10 was this sentence; leaving it on the unknown-version path
3443	          // would have left the same lie behind a narrower door.
3444	          if (srcMajor && dstMajor) {
