3534	async function resolveOnTarget(conn: Client, exe: string): Promise<string> {
3535	  if (!exe) return "";
3536	  if (exe.startsWith("/")) {
3537	    if (validPath(exe) && (await shOk(conn, `test -x ${exe}`))) return exe;
3538	    // Same basename under a different prefix (node, python3, …).
3539	    const base = exe.slice(exe.lastIndexOf("/") + 1);
3540	    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(base)) {
3541	      const found = clean((await sh(conn, `command -v ${base} 2>/dev/null`)).stdout, 255);
3542	      if (validPath(found) && (await shOk(conn, `test -x ${found}`))) return found;
3543	    }
3544	    return "";
3545	  }
3546	  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(exe)) return "";
3547	  const found = clean((await sh(conn, `command -v ${exe} 2>/dev/null`)).stdout, 255);
3548	  return validPath(found) && (await shOk(conn, `test -x ${found}`)) ? found : "";
