3551	/**
3552	 * Turn a captured source command line into an ExecStart that will run on the
3553	 * target: resolve the interpreter/exec (first token) to an absolute target path,
3554	 * keep the remaining args verbatim. Returns "" when the program cannot be
3555	 * resolved here (better to leave the site's honest 502 than write a unit that
3556	 * 203/EXECs forever). Args are validated shell-inert; the ExecStart is written
3557	 * into a unit file (systemd parses it, no shell), never executed through a shell.
3558	 */
3559	async function execStartFromCmdline(conn: Client, cmdline: string): Promise<string> {
3560	  const toks = String(cmdline ?? "").trim().split(/\s+/).filter(Boolean);
3561	  if (!toks.length) return "";
3562	  const exe = await resolveOnTarget(conn, toks[0]);
3563	  if (!exe) return "";
3564	  const rest = toks.slice(1).filter((t) => /^[A-Za-z0-9@%:._/=+-]{1,255}$/.test(t));
3565	  return [exe, ...rest].join(" ");
3566	}
