732	/** Parse a `du -sh`-style size label ("1.2G", "340M", "512K", "1.2 GB") into bytes. */
733	export function parseSizeLabel(label: string): number {
734	  const m = /^([\d.]+)\s*([KMGT]?)/i.exec(label.trim());
735	  if (!m) return 0;
736	  const n = parseFloat(m[1]);
737	  const mult: Record<string, number> = { "": 1, K: 1024, M: 1024 ** 2, G: 1024 ** 3, T: 1024 ** 4 };
738	  return n * (mult[m[2].toUpperCase()] ?? 1);
739	}
