741	/**
742	 * Parse a MySQL/MariaDB client `--version` banner into a variant + major.minor.
743	 * MariaDB banners contain the literal "MariaDB" (e.g. "...Distrib 10.11.6-MariaDB");
744	 * Oracle MySQL banners look like "mysql  Ver 8.0.36 for Linux". Returns
745	 * {variant:null,version:null} when the banner is empty/unrecognised.
746	 */
747	export function parseMysqlVersion(raw: string): { variant: "mysql" | "mariadb" | null; version: string | null } {
748	  const s = cleanText(raw, 200);
749	  if (!s) return { variant: null, version: null };
750	  if (/mariadb/i.test(s)) {
751	    const m = /(\d+\.\d+)(?:\.\d+)?-MariaDB/i.exec(s) || /(\d+\.\d+)/.exec(s);
752	    return { variant: "mariadb", version: m ? m[1] : null };
753	  }
754	  const m = /Ver\s+(\d+\.\d+)/i.exec(s) || /(\d+\.\d+)/.exec(s);
755	  return { variant: "mysql", version: m ? m[1] : null };
756	}
